<template>
  <section class="app-case-reference environment-reference">
    <div class="environment-metrics"><article v-for="item in metrics" :key="item.label" class="app-case-metric" :class="item.tone"><span class="app-case-metric-icon"><component :is="item.icon" /></span><div><span>{{item.label}}</span><strong>{{item.value}}</strong><small>{{item.note}}</small></div></article></div>
    <a-alert v-if="!projectId">选择项目后可管理项目环境；全局执行器配置与诊断仍可使用。</a-alert>
    <a-alert v-if="projectId&&!supported&&!loading&&!error" type="warning">当前 APP 服务尚未加载多环境接口，以下显示真实全局执行器配置。新增、克隆及导入需加载新版 APP 服务后使用；原有执行器配置和诊断仍可使用。</a-alert>
    <a-alert v-if="error" type="error">{{error}}<template #action><a-button size="mini" @click="load">重试</a-button></template></a-alert>
    <div class="environment-workspace">
      <section class="app-case-list environment-list" aria-label="环境配置列表">
        <div class="app-case-toolbar environment-toolbar"><a-input v-model="search" placeholder="搜索环境名称、地址或描述" allow-clear :input-attrs="{'aria-label':'搜索环境'}"><template #prefix><icon-search /></template></a-input><a-select v-model="kind" aria-label="筛选环境类型"><a-option value="">环境类型 · 全部</a-option><a-option v-for="(label,key) in kindLabels" :key="key" :value="key">{{label}}</a-option></a-select><a-select v-model="status" aria-label="筛选环境状态"><a-option value="">状态 · 全部</a-option><a-option value="available">可用</a-option><a-option value="error">异常</a-option><a-option value="maintenance">维护中</a-option><a-option value="unchecked">待检测</a-option></a-select><a-select v-model="platform" aria-label="筛选环境平台"><a-option value="">平台 · 全部</a-option><a-option value="android">Android</a-option><a-option value="ios">iOS</a-option><a-option value="none">不限制</a-option></a-select></div>
        <div class="environment-list-actions"><span v-if="selected.length">已选择 {{selected.length}} 个环境 <a-button type="text" size="mini" @click="selected=[]">清空选择</a-button></span><span v-else>未经检测的环境不会标记为可用</span><a-space wrap><a-button aria-label="重置环境筛选" @click="reset">重置</a-button><a-button :loading="loading" aria-label="刷新环境列表" @click="refresh"><icon-refresh /> 刷新</a-button><a-button @click="emit('executor')"><icon-settings /> 执行器配置</a-button><a-button type="primary" :disabled="!supported||Boolean(error)" @click="open()"><icon-plus /> 新建环境</a-button></a-space></div>
        <a-table class="app-case-table environment-table" :data="pageRows" row-key="id" :pagination="false" :loading="loading" :bordered="false" :scroll="{x:1040}" :row-selection="supported?{type:'checkbox',showCheckedAll:true}:undefined" v-model:selected-keys="selected"><template #columns>
          <a-table-column title="环境名称" :width="180"><template #cell="{record}"><button class="environment-name" :title="record.description" @click="edit(record)">{{record.name}}</button><small class="environment-muted">{{record.description||'未填写说明'}}</small></template></a-table-column>
          <a-table-column title="环境类型" :width="105"><template #cell="{record}"><a-tag :color="record.kind==='cloud'?'purple':record.kind==='service'?'green':'arcoblue'">{{kindLabels[record.kind as keyof typeof kindLabels]}}</a-tag></template></a-table-column>
          <a-table-column title="平台" :width="88"><template #cell="{record}"><span class="environment-platform"><icon-mobile v-if="record.platform!=='none'" :class="record.platform"/>{{record.platform==='none'?'—':record.platform==='ios'?'iOS':'Android'}}</span></template></a-table-column>
          <a-table-column title="设备 / 资源" :width="190"><template #cell="{record}"><span :title="resourceText(record)">{{resourceText(record)}}</span></template></a-table-column>
          <a-table-column title="网络" :width="78"><template #cell="{record}"><span class="environment-platform"><icon-wifi />{{networkLabels[record.network as keyof typeof networkLabels]}}</span></template></a-table-column>
          <a-table-column title="状态" :width="95"><template #cell="{record}"><a-tag :color="environmentStateMeta(record).color">{{environmentStateMeta(record).label}}</a-tag><small class="environment-muted" :title="record.health_message">{{record.checked_at?'已检测':'未检测'}}</small></template></a-table-column>
          <a-table-column title="更新时间" :width="155"><template #cell="{record}">{{formatTime(record.updated_at)}}</template></a-table-column>
          <a-table-column title="操作" :width="120" fixed="right"><template #cell="{record}"><div class="app-case-row-actions"><a-button type="text" :aria-label="`编辑环境 ${record.name}`" :disabled="operating" @click="edit(record)"><icon-edit /></a-button><a-button type="text" :aria-label="`克隆环境 ${record.name}`" :disabled="!supported||operating" @click="open(record,true)"><icon-copy /></a-button><a-dropdown trigger="click"><a-button type="text" :aria-label="`更多环境 ${record.name}`"><icon-more /></a-button><template #content><a-doption :disabled="!supported||operating||!record.enabled" @click="probe([record.id])">连通性检测</a-doption><a-doption :disabled="!supported||operating" @click="batch([record.id],!record.enabled)">{{record.enabled?'设为维护':'启用配置'}}</a-doption><a-doption :disabled="!supported||operating" @click="remove(record)"><span class="environment-danger">删除配置</span></a-doption></template></a-dropdown></div></template></a-table-column>
        </template><template #empty><a-empty :description="rows.length?'没有符合条件的环境':'暂无环境配置，先新建一个运行环境'" /></template></a-table>
        <p class="environment-note">环境启用 / 维护仅管理配置状态，不启动或停止真实服务。点击“连通性检测”检查 ADB 设备或目标 TCP 端口。</p>
        <footer class="app-case-pagination"><span>共 {{filtered.length}} 条</span><a-pagination v-model:current="current" v-model:page-size="pageSize" :total="filtered.length" :show-page-size="width>650" :simple="width<650" :page-size-options="[10,20,50]" /></footer>
      </section>
      <aside class="environment-sidebar">
        <section class="environment-panel"><h3>环境健康</h3><div class="environment-health"><div class="environment-ring" :style="{background:ring}" role="img" :aria-label="`可用 ${stats.available}，异常 ${stats.error}，维护 ${stats.maintenance}，待检测 ${stats.unchecked}`"><div><strong>{{rateText}}</strong><span>可用 / 全部</span></div></div><ul><li v-for="item in distribution" :key="item.label"><i :style="{background:item.color}"/>{{item.label}}<b>{{item.count}}</b></li></ul></div><p class="environment-note">按最近一次检测结果统计，配置更新后需重新检测。</p></section>
        <section class="environment-panel"><h3>环境操作</h3><div class="environment-actions"><a-button :disabled="!canOperate||!selected.length" :loading="operating" @click="probe(selected.map(String))"><icon-thunderbolt /> 检测所选</a-button><a-dropdown trigger="click"><a-button :disabled="!canOperate||!selected.length"><icon-poweroff /> 批量维护</a-button><template #content><a-doption @click="batch(selected.map(String),true)">启用所选配置</a-doption><a-doption @click="batch(selected.map(String),false)">所选设为维护</a-doption></template></a-dropdown><a-button :disabled="!canOperate||selected.length!==1" @click="cloneSelected"><icon-copy /> 环境克隆</a-button><a-dropdown trigger="click"><a-button :disabled="!supported"><icon-import /> 导入 / 导出</a-button><template #content><a-doption @click="fileInput?.click()">导入环境配置</a-doption><a-doption :disabled="!filtered.length||Boolean(error)" @click="exportProfiles">{{selected.length?'导出所选配置':'导出筛选结果'}}</a-doption></template></a-dropdown></div><p class="environment-note">克隆或导入的配置默认处于维护状态。</p></section>
        <section class="environment-panel"><header><h3>使用指引</h3><a-button type="text" size="mini" @click="emit('diagnostics')">运行诊断 <icon-launch /></a-button></header><ol class="environment-guide"><li><icon-check-circle /> 新建环境并填写基本信息</li><li><icon-check-circle /> 关联真实设备或配置服务地址</li><li><icon-check-circle /> 启用配置并进行连通检测</li><li><icon-check-circle /> 在任务中选择设备后执行测试</li></ol><a-alert>当前执行以任务所选设备和全局执行器配置为准；云设备及 iOS 连通检测尚未接入。</a-alert></section>
      </aside>
    </div>
    <a-modal v-model:visible="editorVisible" :title="editingId?'编辑环境':'新建环境'" :width="Math.min(720,width-24)" :mask-closable="!saving" :on-before-ok="save">
      <a-form layout="vertical" :model="draft" class="environment-form"><a-form-item label="环境名称" required><a-input v-model="draft.name" placeholder="例如：Android 真机回归环境" :max-length="120" /></a-form-item><div class="environment-form-grid"><a-form-item label="环境类型"><a-select v-model="draft.kind"><a-option value="device">设备环境</a-option><a-option value="service">服务环境</a-option><a-option value="cloud">云设备环境</a-option><a-option value="dedicated">专项环境</a-option></a-select></a-form-item><a-form-item label="平台"><a-select v-model="draft.platform"><a-option value="android">Android</a-option><a-option value="ios">iOS</a-option><a-option value="none">不限制</a-option></a-select></a-form-item></div><a-form-item label="关联设备"><a-select v-model="draft.device_ids" multiple allow-search allow-clear placeholder="选择当前设备"><a-option v-for="device in devices" :key="device.id" :value="device.id">{{device.name||device.device_id}}</a-option></a-select></a-form-item><a-form-item label="服务检测地址"><a-input v-model="draft.endpoint" placeholder="https://api-test.example.com（仅检查 TCP 端口）" /></a-form-item><div class="environment-form-grid"><a-form-item label="网络"><a-select v-model="draft.network"><a-option value="intranet">内网</a-option><a-option value="cloud">云端</a-option><a-option value="dedicated">专线</a-option></a-select></a-form-item><a-form-item label="启用配置"><a-switch v-model="draft.enabled" /></a-form-item></div><a-form-item label="说明"><a-textarea v-model="draft.description" :max-length="2000" :auto-size="{minRows:2,maxRows:4}" /></a-form-item><a-alert>保存后状态为待检测；修改不会自动启动设备或绑定测试任务。</a-alert></a-form>
    </a-modal>
    <input ref="fileInput" type="file" accept=".json,application/json" hidden @change="readImport" />
    <a-modal v-model:visible="importVisible" title="导入环境配置" :width="Math.min(620,width-24)" :on-before-ok="confirmImport"><a-alert>将新增 {{importPreview.length}} 个环境，不覆盖现有记录。所有导入配置先置为维护状态，检测结果不沿用。</a-alert><ol class="environment-import-preview"><li v-for="(profile,index) in importPreview" :key="index">{{profile.name}} · {{kindLabels[profile.kind]}}</li></ol></a-modal>
  </section>
</template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useWindowSize} from '@vueuse/core'
import {Message} from '@arco-design/web-vue'
import {IconStorage,IconPlayArrow,IconExclamation,IconPause,IconDashboard,IconSearch,IconRefresh,IconSettings,IconPlus,IconMobile,IconWifi,IconEdit,IconCopy,IconMore,IconThunderbolt,IconPoweroff,IconImport,IconLaunch,IconCheckCircle} from '@arco-design/web-vue/es/icon'
import {useEnvironmentWorkspace} from './useEnvironmentWorkspace'
import {kindLabels,networkLabels,environmentState,environmentStateMeta,environmentStats,parseEnvironmentImport,profileInput,type EnvironmentInput,type EnvironmentProfile} from './environmentModels'
import {notificationTime} from '../notifications/notificationPresentation'
import '../test-cases/test-cases-reference.css'
import './settings-reference.css'
const props=defineProps<{projectId:number|null;fallback:EnvironmentProfile}>(),emit=defineEmits<{executor:[];diagnostics:[];refresh:[]}>(),{width}=useWindowSize()
const {profiles,devices,supported,loading,error,saving,editorVisible,draft,busy:_,editingId,operating,load,open,save,remove,batch,probe,importing:__,importRows}=useEnvironmentWorkspace(()=>props.projectId)
const rows=computed(()=>supported.value?profiles.value:[props.fallback]),stats=computed(()=>environmentStats(rows.value)),search=ref(''),kind=ref(''),status=ref(''),platform=ref(''),current=ref(1),pageSize=ref(10),selected=ref<(number|string)[]>([])
const filtered=computed(()=>rows.value.filter(profile=>(!kind.value||profile.kind===kind.value)&&(!status.value||environmentState(profile)===status.value)&&(!platform.value||profile.platform===platform.value)&&[profile.name,profile.endpoint,profile.description].join(' ').toLowerCase().includes(search.value.trim().toLowerCase()))),pageRows=computed(()=>filtered.value.slice((current.value-1)*pageSize.value,current.value*pageSize.value)),canOperate=computed(()=>supported.value&&!error.value&&!operating.value&&!loading.value)
const rateText=computed(()=>stats.value.rate===null?'—':`${stats.value.rate.toFixed(1)}%`)
const metrics=computed(()=>[{label:'环境总数',value:stats.value.total,note:supported.value?'当前项目配置':'当前全局执行器',tone:'teal',icon:IconStorage},{label:'可用环境',value:stats.value.available,note:'最近检测已通过',tone:'teal',icon:IconPlayArrow},{label:'异常环境',value:stats.value.error,note:'需要检查连接',tone:'orange',icon:IconExclamation},{label:'维护中',value:stats.value.maintenance,note:`待检测 ${stats.value.unchecked} 个`,tone:'orange',icon:IconPause},{label:'环境健康度',value:rateText.value,note:'可用环境 / 全部环境',tone:'purple',icon:IconDashboard}])
const distribution=computed(()=>[{label:'可用',count:stats.value.available,color:'#00a88f'},{label:'维护',count:stats.value.maintenance,color:'#f59e0b'},{label:'异常',count:stats.value.error,color:'#ef4444'},{label:'待检测',count:stats.value.unchecked,color:'#d5dde7'}])
const ring=computed(()=>{let sum=0;return !stats.value.total?'#edf1f6':'conic-gradient('+distribution.value.map(item=>{const end=sum+item.count/stats.value.total*100,part=`${item.color} ${sum}% ${end}%`;sum=end;return part}).join(',')+')'})
const formatTime=(value:string)=>Number.isFinite(notificationTime(value))?new Date(notificationTime(value)).toLocaleString('zh-CN',{hour12:false}):'—'
const resourceText=(profile:EnvironmentProfile)=>profile.kind==='executor'?'ADB / 本地执行器':profile.device_ids.length?`${profile.device_ids.length} 台 · ${profile.device_ids.map(id=>devices.value.find(device=>device.id===id)?.name||'#'+id).join('、')}`:profile.endpoint||'尚未配置资源'
const edit=(profile:EnvironmentProfile)=>profile.kind==='executor'?emit('executor'):open(profile)
const refresh=()=>{emit('refresh');void load()}
const reset=()=>{search.value='';kind.value='';status.value='';platform.value='';current.value=1}
const cloneSelected=()=>{const profile=profiles.value.find(item=>item.id===selected.value[0]);if(profile)open(profile,true)}
const fileInput=ref<HTMLInputElement|null>(null),importVisible=ref(false),importPreview=ref<EnvironmentInput[]>([])
const readImport=async(event:Event)=>{const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;try{if(file.size>1024*1024)throw Error('文件不能超过 1 MB');importPreview.value=parseEnvironmentImport(await file.text());importVisible.value=true}catch(value:any){Message.error(value.message||'导入文件无效')}}
const confirmImport=()=>importRows(importPreview.value)
const exportProfiles=()=>{const values=selected.value.length?filtered.value.filter(item=>selected.value.includes(item.id)):filtered.value;if(values.length>100){Message.warning('每次最多导出 100 个环境，请筛选或选择后重试');return}const data={version:1,profiles:values.filter(item=>item.kind!=='executor').map(profileInput)},url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=`FeiCe-环境配置-项目${props.projectId}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
watch([search,kind,status,platform,pageSize],()=>{current.value=1})
watch(filtered,items=>{current.value=Math.min(current.value,Math.max(1,Math.ceil(items.length/pageSize.value)));const ids=new Set(items.map(item=>item.id));selected.value=selected.value.filter(id=>ids.has(String(id)))})
watch(()=>props.projectId,()=>{selected.value=[];importVisible.value=false;reset()})
</script>
